#!/usr/bin/env python3
"""
Generate comprehensive HTML fitness tracker analytics report.
Uses Chart.js for embedded visualizations.
"""

import pandas as pd
import numpy as np
from datetime import datetime
import pickle

# Load pre-computed analysis data
with open('/app/output/analysis_data.pkl', 'rb') as f:
    data = pickle.load(f)

df = data['df']
summary = data['summary_data']

# Re-clean workout type (handle NaN)
df['workout_type_clean'] = df['workout_type'].fillna('None')

# Helper function to format JavaScript arrays
def js_array(d):
    return str(list(d.values())).replace('nan', 'null').replace('None', '"None"')

def js_dict(d):
    items = [f"'{k}': {v}" for k, v in d.items()]
    return '{' + ', '.join(items) + '}'

# Generate report HTML
html = f'''<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
