#!/usr/bin/env python3
"""
Generate comprehensive HTML fitness tracker analytics report.
Uses Chart.js for embedded visualizations.
"""

import pandas as pd
import numpy as np
from datetime import datetime
import pickle

# Load pre-computed analysis data
with open('/app/output/analysis_data.pkl', 'rb') as f:
    data = pickle.load(f)

df = data['df']
summary = data['summary_data']

# Re-clean workout type (handle NaN)
df['workout_type_clean'] = df['workout_type'].fillna('None')

# Calculate actual values from data
workout_types = ['Cycling', 'Gym', 'None', 'Running', 'Walking', 'Yoga']
moods = ['Happy', 'Neutral', 'Stressed', 'Tired']

# Steps by workout type
steps_by_workout = {}
for wt in workout_types:
    subset = df[df['workout_type_clean'] == wt]
    steps_by_workout[wt] = subset['steps'].mean() if len(subset) > 0 else 0

# Steps by mood
steps_by_mood = {}
for m in moods:
    subset = df[df['mood'] == m]
    steps_by_mood[m] = subset['steps'].mean() if len(subset) > 0 else 0

# Sleep by mood
sleep_by_mood = {}
for m in moods:
    subset = df[df['mood'] == m]
    sleep_by_mood[m] = subset['sleep_hours'].mean() if len(subset) > 0 else 0

# Sleep by stress level (1-10)
sleep_by_stress = {}
for sl in range(1, 11):
    subset = df[df['stress_level'] == sl]
    sleep_by_stress[sl] = subset['sleep_hours'].mean() if len(subset) > 0 else 0

# Stress by workout
stress_by_workout = {}
for wt in workout_types:
    subset = df[df['workout_type_clean'] == wt]
    stress_by_workout[wt] = subset['stress_level'].mean() if len(subset) > 0 else 0

# Stress by mood
stress_by_mood = {}
for m in moods:
    subset = df[df['mood'] == m]
    stress_by_mood[m] = subset['stress_level'].mean() if len(subset) > 0 else 0

# Calories by workout
calories_by_workout = {}
for wt in workout_types:
    subset = df[df['workout_type_clean'] == wt]
    calories_by_workout[wt] = subset['calories_burned'].mean() if len(subset) > 0 else 0

# Monthly aggregates
monthly_steps = df.groupby('month')['steps'].mean()
monthly_calories = df.groupby('month')['calories_burned'].mean()
monthly_workout_rate = df.groupby('month').apply(lambda x: (x['workout_type_clean'] != 'None').mean() * 100, include_groups=False)

# Yearly aggregates
yearly_steps = df.groupby('year')['steps'].mean()
yearly_calories = df.groupby('year')['calories_burned'].mean()
yearly_workout_rate = df.groupby('year').apply(lambda x: (x['workout_type_clean'] != 'None').mean() * 100, include_groups=False)
yearly_sleep = df.groupby('year')['sleep_hours'].mean()

# Day of week
dow_labels = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday']
dow_steps = df.groupby('day_of_week')['steps'].mean()
dow_workout_rate = df.groupby('day_of_week').apply(lambda x: (x['workout_type_clean'] != 'None').mean() * 100, include_groups=False)

# Correlations
numeric_cols = ['steps', 'calories_burned', 'sleep_hours', 'heart_rate_avg', 'water_intake_liters', 'stress_level']
corr_with_steps = df[numeric_cols].corr()['steps'].drop('steps')

# Workout type counts
workout_counts = df['workout_type_clean'].value_counts()

# Gender stats
gender_dist = df['gender'].value_counts()

# Mood counts
